import{_ as e,o as t,c as n,a3 as i}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"交付与演进","description":"把项目范围、技术方案、生产验收和生命周期管理连接成可追踪的交付证据链。","frontmatter":{"title":"交付与演进","description":"把项目范围、技术方案、生产验收和生命周期管理连接成可追踪的交付证据链。"},"headers":[],"relativePath":"py-agent/architecture/delivery-evolution/index.md","filePath":"py-agent/architecture/delivery-evolution/index.md","lastUpdated":1786083160000}'),s={name:"py-agent/architecture/delivery-evolution/index.md"};function l(r,a,o,p,d,c){return t(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="交付与演进" tabindex="-1">交付与演进 <a class="header-anchor" href="#交付与演进" aria-label="Permalink to &quot;交付与演进&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>Agent 项目能演示，不等于能够交付。本分组从项目开始时的范围契约出发，组织架构决策和技术方案，在候选版本上线前汇总生产证据，并在上线后管理迭代、能力版本、用户迁移、弃用和退役。</p><h2 id="_1-学习目标" tabindex="-1">1. 学习目标 <a class="header-anchor" href="#_1-学习目标" aria-label="Permalink to &quot;1. 学习目标&quot;">​</a></h2><p>完成本分组后，你应该能够：</p><ol><li>把业务目标、用户任务、自动化等级和排除范围写成共同项目契约；</li><li>为功能、质量、安全、性能、可靠性、运营和成本定义验收证据；</li><li>使用系统视图、运行流程、数据设计、ADR 和风险实验组织技术方案；</li><li>用不可变 Release Manifest 固定一次候选的完整行为与数据版本；</li><li>组织生产就绪评审、Go/No-Go、Canary、停止条件和发布后验收；</li><li>从错误和运行数据形成可测迭代假设，而不是不断追加 Prompt 规则；</li><li>管理能力版本和用户迁移，并把底层技术兼容交给对应生产专题；</li><li>在价值不足或风险不可接受时完整下线任务、数据、身份和基础设施。</li></ol><h2 id="_2-文章顺序" tabindex="-1">2. 文章顺序 <a class="header-anchor" href="#_2-文章顺序" aria-label="Permalink to &quot;2. 文章顺序&quot;">​</a></h2><ol><li><a href="/py-agent/architecture/delivery-evolution/project-scope-acceptance">项目范围与验收标准</a>：定义项目解决什么、不做什么以及怎样判定完成。</li><li><a href="/py-agent/architecture/delivery-evolution/architecture-decisions-technical-design">架构决策与技术方案</a>：把架构驱动因素转成视图、流程、ADR、实验和实施切分。</li><li><a href="/py-agent/architecture/delivery-evolution/production-readiness-release-acceptance">生产就绪与发布验收</a>：汇总候选版本的质量、安全、运行和组织证据，形成 Go/No-Go。</li><li><a href="/py-agent/architecture/delivery-evolution/iteration-migration-retirement">迭代与生命周期治理</a>：根据真实结果迭代能力，并管理用户迁移、弃用和最终退役。</li></ol><p>四篇文章对应项目生命周期中的范围、方案、上线和演进。后一步发现证据不足时，应返回前一步修改范围或设计，而不是带着未解决风险继续推进。</p><h2 id="_3-证据链" tabindex="-1">3. 证据链 <a class="header-anchor" href="#_3-证据链" aria-label="Permalink to &quot;3. 证据链&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>业务结果与用户任务</span></span>
<span class="line"><span>  -&gt; 范围、排除项和验收标准</span></span>
<span class="line"><span>  -&gt; 架构视图、ADR 与风险实验</span></span>
<span class="line"><span>  -&gt; 实现、测试、评测和运行证据</span></span>
<span class="line"><span>  -&gt; Release Manifest 与 Go/No-Go</span></span>
<span class="line"><span>  -&gt; 真实流量结果与误差分析</span></span>
<span class="line"><span>  -&gt; 迭代、保持、弃用或退役</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>每个关键对象都应有稳定 ID 和版本，例如需求、ADR、测试、评测运行和发布候选。这样才能从一次生产失败追溯到当时的模型、Prompt、工具、Workflow、索引和批准依据。</p><h2 id="_4-阶段产物" tabindex="-1">4. 阶段产物 <a class="header-anchor" href="#_4-阶段产物" aria-label="Permalink to &quot;4. 阶段产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>最小产物</th><th>不能替代它的东西</th></tr></thead><tbody><tr><td>范围</td><td>项目简报、任务目录、验收矩阵、责任人</td><td>产品愿景或演示视频</td></tr><tr><td>方案</td><td>系统视图、运行流程、ADR、风险实验</td><td>云产品清单或一张组件图</td></tr><tr><td>发布</td><td>Manifest、门禁证据、Canary、回滚、Runbook</td><td>“测试都绿了”或镜像已部署</td></tr><tr><td>演进</td><td>错误分类、变化假设、配对结果、用户迁移与退役记录</td><td>用户点赞或模型排行榜变化</td></tr></tbody></table><p>模板必须被填写并连接到真实证据。空白清单只能提醒遗漏，不能证明项目已经完成。</p><h2 id="_5-分组边界" tabindex="-1">5. 分组边界 <a class="header-anchor" href="#_5-分组边界" aria-label="Permalink to &quot;5. 分组边界&quot;">​</a></h2><p>本组负责交付决策和证据组织，不重复测试框架、评测算法、部署平台或数据库迁移的完整机制。这些内容由“质量与生产”“Agent 应用工程”和“工作流与多 Agent”负责。</p><p>“项目实战”展示具体系统怎样实现；本组说明团队怎样确定项目完成、批准上线、管理变化并承担长期责任。两者结合后，实战才不止是代码样例，交付也不止是抽象流程。</p>`,18)])])}const b=e(s,[["render",l]]);export{u as __pageData,b as default};
